\begin{tikzpicture}[font=\sffamily, scale=1]

    % Vertical cliff
    \draw[thick] (0,-0.5) -- (0,7);
    \surface{(0,-0.5)}{(0,7)}{-1} % Ground/cliff hatching on the left (-1 side)

    % Rock climber representation (simple stick figure / block outline)
    % Let's draw a simplified climber: body, head, feet against the wall
    \coordinate (feet) at (0, 1.5);
    \coordinate (body) at (1.2, 3.2);
    \coordinate (head) at (1.2, 4.7);
    \coordinate (hands) at (1.5, 4.0);

    % Head
    \draw[thick, fill=white] (head) circle (0.35);

    % Body
    \draw[thick] (1.2, 4.35) -- (1.2, 2.2);

    % Legs (from feet at cliff to body)
    \draw[thick] (0, 1.5) -- (1.2, 2.2);

    % Arms (holding rope)
    \draw[thick] (1.2, 3.7) -- (2.5, 5.5);

    % Rope extending upwards to the cliff top
    \draw[thick, dashed] (2.5, 5.5) -- (2.5, 6.8);
    \fill (2.5, 6.8) circle (0.08);
    \node[above] at (2.5, 6.8) {fixed point};

    % Ground at the bottom (optional, cliff continues down)
    \draw[thick] (0,-0.5) -- (2.5,-0.5);
    \surface{(0,-0.5)}{(2.5,-0.5)}{-1}

    % Fig label
    \node[below, font=\sffamily] at (1.5, -1.0) {Fig. 2.1};

\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily, scale=1]

    % Vertical cliff
    \draw[thick] (0,0) -- (0,7);
    \surface{(0,0)}{(0,7)}{-1} % Ground/cliff hatching on the left (-1 side)

    % Rock climber representation (simple stick figure / block outline)
    \coordinate (feet) at (0, 2.0);
    \coordinate (body) at (1.2, 3.2);
    \coordinate (head) at (1.2, 4.7);

    % Head
    \draw[thick, fill=white] (head) circle (0.35);

    % Body
    \draw[thick] (1.2, 4.35) -- (1.2, 2.2);

    % Legs (from feet at cliff to body)
    \draw[thick] (0, 2.0) -- (1.2, 2.2);

    % Arms 
    \draw[thick] (1.2, 3.7) -- (2.0, 4.2);

    % Ground at the bottom
    \draw[thick] (0,0) -- (2.5,0);
    \surface{(0,0)}{(2.5,0)}{-1}

    % Fig label
    \node[below, font=\sffamily] at (1.25, -0.5) {Fig. 2.1};

\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily, scale=1]

    % Vertical cliff
    \draw[thick] (0,0) -- (0,7);
    \surface{(0,0)}{(0,7)}{-1} % Ground/cliff hatching on the left (-1 side)

    % Rock climber representation (simple stick figure / block outline)
    \coordinate (feet) at (0, 2.0);
    \coordinate (body) at (1.2, 3.2);
    \coordinate (head) at (1.2, 4.7);

    % Head
    \draw[thick, fill=white] (head) circle (0.35);

    % Body
    \draw[thick] (1.2, 4.35) -- (1.2, 2.2);

    % Legs (from feet at cliff to body)
    \draw[thick] (0, 2.0) -- (1.2, 2.2);

    % Arms 
    \draw[thick] (1.2, 3.7) -- (2.3, 4.5);

    % Force vectors and labels
    % Weight (acting downwards from center of mass/body)
    \draw[-{Stealth[length=2.5mm]}, thick] (1.2, 3.2) -- (1.2, 1.2) node[right] {Weight};

    % Tension (acting upwards-right along the rope direction)
    \draw[-{Stealth[length=2.5mm]}, thick] (2.3, 4.5) -- (3.0, 5.0) node[above right] {$T$};

    % Normal force from cliff (pressing feet against cliff -> force on climber is away from cliff, or force by feet on cliff. Wait, force *pressing* feet against cliff is 300 N, normal reaction is outward. Let's show forces *on* the climber: normal force from cliff to the right)
    \draw[-{Stealth[length=2.5mm]}, thick] (0, 2.0) -- (1.0, 2.0) node[above] {Normal};

    % Friction acting between feet and cliff (upwards)
    \draw[-{Stealth[length=2.5mm]}, thick] (0, 2.0) -- (0, 3.2) node[left] {Friction};

    % Ground at the bottom
    \draw[thick] (0,0) -- (3.5,0);
    \surface{(0,0)}{(3.5,0)}{-1}

    % Fig label
    \node[below, font=\sffamily] at (1.75, -0.5) {Fig. 2.1};

\end{tikzpicture}
